insert into public.clauses (clause_id, version, type, title, variant, templates, deviation_cost, alternative_of, body, context) values
('DEF-AFFILIATE','v1','definition','Definition of "Affiliate"','definition',array['NDA','IMA','DIST','SIDE','SUBS']::text[],0.0,null,'"Affiliate" means, in relation to a party, any entity that directly or indirectly controls, is controlled by, or is under common control with that party, where control means the ownership of more than 50 per cent. of the voting rights or the power to appoint a majority of the board.','This chunk defines the term "Affiliate" within the context of the Mutual Non-Disclosure Agreement.'),
('DEF-APPLICABLE-LAW','v1','definition','Definition of "Applicable Law"','definition',array['NDA','IMA','DIST','SUBS']::text[],0.0,null,'"Applicable Law" means all laws, regulations, notices, guidelines and directions of any governmental or regulatory authority (including the Monetary Authority of Singapore) that apply to a party or to the subject matter of this Agreement, as amended from time to time.','This chunk defines "Applicable Law" within the context of the Mutual Non-Disclosure Agreement.'),
('DEF-BUSINESS-DAY','v1','definition','Definition of "Business Day"','definition',array['NDA','IMA','DIST','SIDE','SUBS']::text[],0.0,null,'"Business Day" means a day (other than a Saturday, Sunday or gazetted public holiday) on which commercial banks are open for general business in Singapore.','This chunk defines what constitutes a "Business Day" within the context of the Mutual Non-Disclosure Agreement.'),
('DEF-CONFIDENTIAL-INFORMATION','v1','definition','Definition of "Confidential Information"','definition',array['NDA']::text[],0.0,null,'"Confidential Information" means all information, in any form, disclosed by or on behalf of the Disclosing Party to the Receiving Party in connection with the Purpose, including investment strategies, portfolio holdings, pricing, client identities and terms of business, together with all notes and analyses prepared from such information.','This chunk defines what constitutes "Confidential Information" within the context of the Mutual Non-Disclosure Agreement.'),
('DEF-PURPOSE','v1','definition','Definition of "Purpose"','definition',array['NDA']::text[],0.0,null,'"Purpose" means the evaluation, negotiation and, if agreed, implementation of a possible business relationship between the parties concerning investment management or fund distribution services.','This chunk defines the term "Purpose," which is crucial for understanding the scope of the mutual non-disclosure agreement.'),
('DEF-REPRESENTATIVES','v1','definition','Definition of "Representatives"','definition',array['NDA']::text[],0.0,null,'"Representatives" means, in relation to a party, its Affiliates and its and their directors, officers, employees, professional advisers and auditors who need to know the Confidential Information for the Purpose.','This chunk defines what constitutes "Representatives" under the Mutual Non-Disclosure Agreement, specifying the individuals who are covered under the agreement''s confidentiality obligations.'),
('DEF-PERSONAL-DATA','v1','definition','Definition of "Personal Data"','definition',array['NDA','IMA','DIST','SUBS']::text[],0.0,null,'"Personal Data" has the meaning given to it in the Personal Data Protection Act 2012 of Singapore.','This chunk defines "Personal Data" and its context is within the Definitions section of the Mutual Non-Disclosure Agreement.'),
('DEF-CLIENT','v1','definition','Definition of "Client"','definition',array['IMA']::text[],0.0,null,'"Client" means the person named as the client in the Schedule, being an accredited investor or institutional investor within the meaning of the Securities and Futures Act 2001.','This chunk defines the term "Client" within the context of the Investment Management Agreement, specifying the criteria for who qualifies as a Client.'),
('DEF-INVESTMENT-MANAGER','v1','definition','Definition of "Investment Manager"','definition',array['IMA','DIST','SIDE','SUBS']::text[],0.0,null,'"Investment Manager" means the fund management company named in the Schedule, which holds a capital markets services licence for fund management issued by the Monetary Authority of Singapore.','This chunk defines the term "Investment Manager" within the context of the Investment Management Agreement, specifying the requirements for the named entity.'),
('DEF-PORTFOLIO','v1','definition','Definition of "Portfolio"','definition',array['IMA']::text[],0.0,null,'"Portfolio" means the cash, securities and other assets of the Client placed under the management of the Investment Manager under this Agreement, together with all income and proceeds.','This definition is provided under the Definitions section (1.6) and explains what constitutes the Portfolio in the Investment Management Agreement.'),
('DEF-NAV','v1','definition','Definition of "Net Asset Value"','definition',array['IMA','SIDE','SUBS']::text[],0.0,null,'"Net Asset Value" means the value of the assets of the Portfolio or the Fund (as the context requires) less its liabilities, calculated by the administrator in accordance with the valuation policy in force.','This chunk defines the term "Net Asset Value," which is used in the document to calculate the value of the Portfolio or Fund, less its liabilities, as required by the valuation policy.'),
('DEF-MANAGEMENT-FEE','v1','definition','Definition of "Management Fee"','definition',array['IMA','DIST','SIDE']::text[],0.0,null,'"Management Fee" means the fee payable to the Investment Manager for its management services, calculated in accordance with Clause 9 (Management Fee).','This chunk defines the term "Management Fee" within the context of the Investment Management Agreement, specifying that it is calculated according to Clause 9.'),
('DEF-PERFORMANCE-FEE','v1','definition','Definition of "Performance Fee"','definition',array['IMA']::text[],0.0,null,'"Performance Fee" means the fee payable to the Investment Manager by reference to the increase in Net Asset Value above the High-Water Mark.','This chunk defines the term "Performance Fee" within the context of the Investment Management Agreement, specifying when and how it is calculated.'),
('DEF-HIGH-WATER-MARK','v1','definition','Definition of "High-Water Mark"','definition',array['IMA']::text[],0.0,null,'"High-Water Mark" means the highest Net Asset Value at the end of any previous performance period in respect of which a Performance Fee was paid, adjusted for subscriptions and withdrawals.','This chunk defines the term "High-Water Mark," which is used in the context of calculating the Performance Fee.'),
('DEF-KEY-PERSON','v1','definition','Definition of "Key Person"','definition',array['IMA','SIDE']::text[],0.0,null,'"Key Person" means the individual or individuals named as key persons in the Schedule or in the Fund Documents, being the portfolio managers principally responsible for investment decisions.','This chunk defines the term "Key Person" within the context of the Investment Management Agreement, specifying who is responsible for investment decisions.'),
('DEF-CUSTODIAN','v1','definition','Definition of "Custodian"','definition',array['IMA']::text[],0.0,null,'"Custodian" means the bank or trust company appointed by the Client to hold the assets of the Portfolio, which shall be independent of the Investment Manager.','This definition is provided under the section on Definitions, explaining the role and independence of the Custodian in the investment management agreement.'),
('DEF-LOSSES','v1','definition','Definition of "Losses"','definition',array['IMA','DIST','SUBS']::text[],0.0,null,'"Losses" means all losses, liabilities, damages, costs (including reasonable legal fees) and expenses, but excluding indirect or consequential loss and loss of profit.','This chunk defines the term "Losses" within the context of the Investment Management Agreement, specifying what is included and excluded from this definition.'),
('DEF-SANCTIONS','v1','definition','Definition of "Sanctions"','definition',array['IMA','DIST','SUBS']::text[],0.0,null,'"Sanctions" means any economic or financial sanctions or trade embargoes administered by the United Nations, Singapore (including under the Monetary Authority of Singapore Act 1970), the European Union, the United Kingdom or the United States, and Sanctioned Person means any person who is the target of Sanctions.','This chunk defines "Sanctions" and "Sanctioned Person" within the context of regulatory compliance and risk management in investment management agreements.'),
('DEF-DISTRIBUTOR','v1','definition','Definition of "Distributor"','definition',array['DIST']::text[],0.0,null,'"Distributor" means the person appointed under this Agreement to market and arrange subscriptions for Shares, as named in the Schedule.','This definition is provided under the Definitions section and explains the term "Distributor" in the context of the Distribution Agreement.'),
('DEF-FUND','v1','definition','Definition of "Fund"','definition',array['DIST','SIDE','SUBS']::text[],0.0,null,'"Fund" means the open-ended investment fund (including any variable capital company sub-fund) managed by the Investment Manager and described in the Fund Documents.','This chunk defines the term "Fund" within the context of the Distribution Agreement, specifying its management and description.'),
('DEF-SHARES','v1','definition','Definition of "Shares"','definition',array['DIST','SIDE','SUBS']::text[],0.0,null,'"Shares" means participating shares or units of any class in the Fund.','This definition of "Shares" is provided under the Definitions section, setting the groundwork for understanding the terms used throughout the agreement.'),
('DEF-TERRITORY','v1','definition','Definition of "Territory"','definition',array['DIST']::text[],0.0,null,'"Territory" means Singapore and any other jurisdiction set out in the Schedule as agreed in writing from time to time.','This chunk defines the term "Territory" within the context of the Distribution Agreement, specifying that it includes Singapore and any additional jurisdictions agreed upon in writing.'),
('DEF-ELIGIBLE-INVESTOR','v1','definition','Definition of "Eligible Investor"','definition',array['DIST','SUBS']::text[],0.0,null,'"Eligible Investor" means an accredited investor or institutional investor within the meaning of section 4A of the Securities and Futures Act 2001, or an equivalent professional investor in another part of the Territory.','This chunk defines the term "Eligible Investor," which is used in the context of marketing and selling Shares to appropriate investors as per the agreement''s terms and conditions.'),
('DEF-INVESTOR','v1','definition','Definition of "Investor"','definition',array['SIDE','SUBS']::text[],0.0,null,'"Investor" means the person named as the investor in this letter, including any permitted transferee of its interest in the Fund.','This chunk defines the term "Investor" within the document, specifying who qualifies as an Investor.'),
('DEF-SIMILAR-INVESTOR','v1','definition','Definition of "Similar Investor"','definition',array['SIDE']::text[],0.0,null,'"Similar Investor" means any other investor in the Fund whose aggregate subscription is equal to or less than the subscription of the Investor, excluding Affiliates of the Investment Manager and employee vehicles.','This chunk defines the term "Similar Investor" within the document''s definitions section.'),
('DEF-FUND-DOCUMENTS','v1','definition','Definition of "Fund Documents"','definition',array['DIST','SIDE','SUBS']::text[],0.0,null,'"Fund Documents" means the constitution, private placement memorandum and subscription documents of the Fund, each as amended from time to time.','This chunk defines "Fund Documents," which is situated in the Definitions section (Clause 1.10) of the Distribution Agreement.'),
('DEF-DEALING-DAY','v1','definition','Definition of "Dealing Day"','definition',array['DIST','SIDE','SUBS']::text[],0.0,null,'"Dealing Day" means the first Business Day of each calendar month and any other day determined by the directors of the Fund.','This definition is provided under the Definitions section (Clause 1.13) of the Distribution Agreement.'),
('DEF-SUBSCRIPTION-AMOUNT','v1','definition','Definition of "Subscription Amount"','definition',array['DIST','SUBS']::text[],0.0,null,'"Subscription Amount" means the amount in the base currency of the Fund that the Investor applies to invest, as stated in the subscription form.','This definition is provided under the Definitions section (Clause 1.13) of the Distribution Agreement, explaining the term "Subscription Amount" used throughout the document.'),
('BP-CONFIDENTIALITY','v1','confidentiality','Confidentiality','standard',array['DIST','IMA','SIDE']::text[],0.0,null,'Each party shall keep confidential all information received from the other party in connection with this Agreement and shall not disclose it except to its Representatives, its auditors and regulators, or as required by Applicable Law. This obligation survives termination of this Agreement for three years.','This chunk is part of Clause 13, which deals with confidentiality obligations between the parties.'),
('BP-DATA-PDPA','v1','data_protection','Data Protection','standard',array['DIST','IMA','NDA','SUBS']::text[],0.0,null,'Each party shall comply with the Personal Data Protection Act 2012 in respect of any Personal Data it collects, uses or discloses in connection with this Agreement. A party shall only process Personal Data received from the other party for the purposes of this Agreement, shall protect it with reasonable security arrangements and shall notify the other party without undue delay of any data breach affecting such Personal Data.','This chunk is located under Clause 10 of the Mutual Non-Disclosure Agreement, addressing data protection obligations between the parties.'),
('BP-DATA-CROSSBORDER','v1','data_transfer','Cross-Border Transfer of Personal Data','optional',array['ALL']::text[],0.0,null,'A party may transfer Personal Data outside Singapore only where the recipient is bound by legally enforceable obligations to provide a standard of protection comparable to that under the Personal Data Protection Act 2012, and shall on request provide the other party with details of the jurisdictions to which Personal Data is transferred and the safeguards applied.','This chunk pertains to the transfer of personal data across borders and is located under the section on Cross-Border Transfer of Personal Data.'),
('BP-AML-KYC','v1','aml_kyc','Anti-Money Laundering and Customer Due Diligence','standard',array['DIST','IMA','SUBS']::text[],0.0,null,'Each party shall comply with Applicable Law on the prevention of money laundering and the financing of terrorism, including MAS Notice SFA04-N02, and shall promptly provide such customer due diligence information and documents as the other party reasonably requests to meet its own obligations.','This chunk is situated in Clause 15 of the Investment Management Agreement, addressing compliance with anti-money laundering and customer due diligence requirements.'),
('BP-SANCTIONS','v1','sanctions','Sanctions','standard',array['DIST','IMA','SUBS']::text[],0.0,null,'Each party represents that neither it nor any of its Affiliates is a Sanctioned Person, and undertakes not to use any monies or assets in connection with this Agreement for the benefit of a Sanctioned Person or in breach of Sanctions.','This chunk is part of the "Sanctions" section, which outlines the obligations of both parties regarding compliance with sanctions laws and the prohibition of transactions with sanctioned persons.'),
('BP-ANTI-BRIBERY','v1','anti_bribery','Anti-Bribery and Corruption','optional',array['ALL']::text[],0.0,null,'Each party shall comply with the Prevention of Corruption Act 1960 and all other applicable anti-bribery laws, shall not offer or accept any inducement in connection with this Agreement, and shall maintain adequate procedures designed to prevent bribery by persons acting on its behalf.','This chunk is part of the Anti-Bribery and Corruption clause (B2) in the document, which outlines the obligations of the parties regarding compliance with anti-bribery laws and the prevention of bribery.'),
('BP-TERMINATION-90','v1','termination_convenience','Termination on Notice','standard',array['DIST','IMA']::text[],0.0,null,'Either party may terminate this Agreement at any time by giving not less than ninety days'' written notice to the other party. Termination shall not affect any rights or obligations that have accrued before the date of termination.','This chunk is part of the Termination on Notice clause, which outlines the conditions and procedures for terminating the agreement by providing written notice.'),
('BP-TERMINATION-30','v1','termination_convenience','Termination on Short Notice','fallback',array['ALL']::text[],0.4,'BP-TERMINATION-90','Either party may terminate this Agreement by giving not less than thirty days'' written notice to the other party, without penalty. Fees shall be apportioned to the date of termination.','This chunk pertains to clause B3, which outlines the conditions for terminating the agreement without penalty.'),
('BP-TERMINATION-CAUSE','v1','termination_cause','Termination for Cause','standard',array['DIST','IMA']::text[],0.0,null,'Either party may terminate this Agreement immediately by written notice if the other party commits a material breach which is not remedied within thirty days of notice, becomes insolvent, or ceases to hold any licence or authorisation required by Applicable Law to perform this Agreement.','This chunk is part of the Termination for Cause clause, detailing the conditions under which either party can terminate the agreement immediately.'),
('BP-FORCE-MAJEURE','v1','force_majeure','Force Majeure','standard',array['IMA']::text[],0.0,null,'Neither party shall be liable for any delay or failure to perform caused by events beyond its reasonable control, including natural disasters, epidemics, war, market closures or failure of settlement systems, provided that it notifies the other party promptly and uses reasonable efforts to mitigate the effect.','This chunk is part of Clause 19, which outlines the conditions under which neither party is liable for delays or failures to perform due to events beyond their reasonable control.'),
('BP-NOTICES','v1','notices','Notices','standard',array['DIST','IMA','NDA','SIDE','SUBS']::text[],0.0,null,'Any notice under this Agreement shall be in writing and delivered by hand or sent by registered post to the address of the recipient set out in the Schedule. A notice is deemed received on delivery by hand or three Business Days after posting.','This chunk is located under the "Notices" section, which specifies how notices under the Agreement should be delivered and deemed received.'),
('BP-NOTICES-EMAIL','v1','notices','Notices by Email','fallback',array['ALL']::text[],0.2,'BP-NOTICES','Any notice under this Agreement may be given by email to the address set out in the Schedule and is deemed received when sent, unless the sender receives an automated message that the email has not been delivered. Notices of termination shall also be sent by registered post.','This chunk pertains to clause B4, detailing the method and acknowledgment of notices under the agreement, including termination notices.'),
('BP-ASSIGNMENT-NONE','v1','assignment','Assignment','standard',array['DIST','IMA','NDA']::text[],0.0,null,'Neither party may assign, transfer or novate any of its rights or obligations under this Agreement without the prior written consent of the other party.','This chunk pertains to clause 12 of the document, which outlines the conditions under which the parties can assign their rights or obligations under the Agreement.'),
('BP-ASSIGNMENT-AFFILIATE','v1','assignment','Assignment to Affiliates','fallback',array['ALL']::text[],0.3,'BP-ASSIGNMENT-NONE','Either party may assign its rights under this Agreement to an Affiliate on written notice to the other party, provided that the assignee holds all licences required by Applicable Law and the assignor remains liable for the assignee''s performance.','This chunk pertains to clause B5, which outlines the conditions under which a party may assign its rights under the agreement to an Affiliate.'),
('BP-ENTIRE','v1','entire_agreement','Entire Agreement','standard',array['DIST','IMA','NDA','SUBS']::text[],0.0,null,'This Agreement constitutes the entire agreement between the parties relating to its subject matter and supersedes all prior negotiations, representations and understandings, whether written or oral.','This chunk is located under Clause 13, which states that the Agreement constitutes the entire agreement between the parties and supersedes all prior negotiations and understandings.'),
('BP-SEVERABILITY','v1','severability','Severability','standard',array['NDA']::text[],0.0,null,'If any provision of this Agreement is held invalid or unenforceable, that provision shall be severed and the remaining provisions shall continue in full force and effect.','This chunk defines the severability clause, which outlines what happens if a provision of the Agreement is found to be invalid or unenforceable.'),
('BP-VARIATION','v1','variation','Variation','standard',array['DIST','IMA','NDA']::text[],0.0,null,'No variation of this Agreement shall be effective unless it is in writing and signed by or on behalf of each of the parties.','This chunk is located under the "Variation" section, which specifies the requirements for amending the agreement.'),
('BP-COUNTERPARTS','v1','counterparts','Counterparts','standard',array['NDA','SIDE']::text[],0.0,null,'This Agreement may be executed in any number of counterparts, each of which is an original and all of which together constitute one instrument.','This chunk defines how multiple counterparts of the agreement can be executed, each being considered an original and together forming one instrument.'),
('BP-ESIGN','v1','electronic_signature','Electronic Signatures','optional',array['ALL']::text[],0.0,null,'The parties agree that this Agreement may be signed by electronic signature in accordance with the Electronic Transactions Act 2010, and that an electronically signed copy shall be as valid and binding as an original signed in wet ink.','This chunk pertains to clause B6, which addresses electronic signatures and their validity in the context of the agreement.'),
('BP-THIRD-PARTY','v1','third_party_rights','Third Party Rights','standard',array['IMA','NDA','SIDE']::text[],0.0,null,'A person who is not a party to this Agreement has no right under the Contracts (Rights of Third Parties) Act 2001 to enforce any of its terms.','This chunk defines the rights of third parties in relation to the agreement, specifying that non-parties cannot enforce its terms.'),
('BP-GOVLAW-SG','v1','governing_law','Governing Law','standard',array['DIST','IMA','NDA','SIDE','SUBS']::text[],0.0,null,'This Agreement and any non-contractual obligations arising out of it are governed by the laws of Singapore.','This chunk specifies the governing law for the agreement and related obligations.'),
('BP-GOVLAW-EW','v1','governing_law','Governing Law (England and Wales)','fallback',array['ALL']::text[],0.6,'BP-GOVLAW-SG','This Agreement and any non-contractual obligations arising out of it are governed by the laws of England and Wales.','This chunk specifies the governing law for the agreement, indicating that it falls under B7 of the document.'),
('BP-DISPUTE-SIAC','v1','dispute_resolution','Arbitration','standard',array['DIST','IMA','NDA','SIDE','SUBS']::text[],0.0,null,'Any dispute arising out of or in connection with this Agreement shall be referred to and finally resolved by arbitration in Singapore administered by the Singapore International Arbitration Centre in accordance with its arbitration rules for the time being in force. The tribunal shall consist of one arbitrator and the language of the arbitration shall be English.','This chunk defines the arbitration clause, specifying how disputes related to the Agreement will be resolved.'),
('BP-DISPUTE-SG-COURTS','v1','dispute_resolution','Jurisdiction of the Singapore Courts','fallback',array['ALL']::text[],0.4,'BP-DISPUTE-SIAC','The courts of Singapore have exclusive jurisdiction to settle any dispute arising out of or in connection with this Agreement, and each party irrevocably submits to the jurisdiction of those courts.','This chunk pertains to clause B8, which specifies the jurisdiction of the Singapore Courts for resolving disputes related to the agreement.'),
('BP-DISPUTE-LCIA','v1','dispute_resolution','Arbitration (London)','fallback',array['ALL']::text[],0.7,'BP-DISPUTE-SIAC','Any dispute arising out of or in connection with this Agreement shall be referred to and finally resolved by arbitration under the rules of the London Court of International Arbitration. The seat of arbitration shall be London and the tribunal shall consist of one arbitrator.','This chunk pertains to clause B9, which outlines the arbitration process for resolving disputes under the agreement.'),
('BP-LIAB-CAP-FEES','v1','limitation_of_liability','Limitation of Liability','optional',array['ALL']::text[],0.0,null,'Except in the case of fraud or wilful default, each party''s aggregate liability under or in connection with this Agreement shall not exceed the total fees paid or payable under this Agreement in the twelve months preceding the event giving rise to the claim, and neither party shall be liable for indirect or consequential loss or loss of profit.','This chunk is part of the "Limitation of Liability" clause (B10) in the document, outlining the conditions under which parties are not liable for certain types of losses.'),
('BP-LIAB-CAP-FIXED','v1','limitation_of_liability','Limitation of Liability (Fixed Cap)','fallback',array['ALL']::text[],0.5,'BP-LIAB-CAP-FEES','Except in the case of fraud or wilful default, each party''s aggregate liability under or in connection with this Agreement shall not exceed one million Singapore dollars, and neither party shall be liable for indirect or consequential loss or loss of profit.','This chunk is part of the Limitation of Liability clause, specifying a fixed cap on liability.'),
('NDA-CONF-OBLIG','v1','nda_confidentiality_obligation','Confidentiality Obligations','standard',array['NDA']::text[],0.0,null,'The Receiving Party shall keep the Confidential Information confidential, shall use at least the same degree of care to protect it as it uses for its own confidential information (and no less than reasonable care), and shall not disclose it to any person except as permitted by Clause 5 (Permitted Disclosure). Each party is both a Disclosing Party and a Receiving Party under this Agreement.','This chunk defines the confidentiality obligations of the Receiving Party and clarifies that each party is both a Disclosing Party and a Receiving Party under the agreement.'),
('NDA-CONF-OBLIG-STRICT','v1','nda_confidentiality_obligation','Confidentiality Obligations (Enhanced)','fallback',array['NDA']::text[],0.5,'NDA-CONF-OBLIG','The Receiving Party shall keep the Confidential Information strictly confidential, shall disclose it only to those Representatives who have signed a written confidentiality undertaking on terms no less protective than this Agreement, and shall keep a register of all persons to whom Confidential Information has been disclosed, which it shall provide to the Disclosing Party on request.','This chunk is part of the Confidentiality Obligations (Enhanced) section, detailing how the Receiving Party must handle and disclose Confidential Information.'),
('NDA-ONE-WAY-OBLIG','v1','nda_confidentiality_obligation','Confidentiality Obligations (One-Way)','fallback',array['NDA']::text[],0.3,'NDA-CONF-OBLIG','Only the Investment Manager discloses Confidential Information under this Agreement. The counterparty, as Receiving Party, shall keep the Confidential Information confidential and shall not disclose it except as permitted by Clause 5 (Permitted Disclosure); the Investment Manager gives no reciprocal confidentiality undertaking.','This chunk outlines the confidentiality obligations where only the Investment Manager discloses Confidential Information, and the counterparty''s obligation to keep it confidential, without a reciprocal undertaking from the Investment Manager.'),
('NDA-PURPOSE-USE','v1','nda_use_restriction','Use of Confidential Information','standard',array['NDA']::text[],0.0,null,'The Receiving Party shall use the Confidential Information solely for the Purpose and shall not use it to trade in any securities, to solicit any client of the Disclosing Party, or for any other commercial advantage.','This chunk defines the permissible use of Confidential Information by the Receiving Party, specifying that it must be used solely for the Purpose and not for trading, solicitation, or other commercial gain.'),
('NDA-EXCLUSIONS','v1','nda_exclusions','Exceptions','standard',array['NDA']::text[],0.0,null,'The obligations in Clause 2 (Confidentiality Obligations) do not apply to Confidential Information that (a) is or becomes publicly available other than through a breach of this Agreement, (b) was lawfully in the Receiving Party''s possession before disclosure, (c) is received from a third party free of any duty of confidence, or (d) is independently developed by the Receiving Party without use of the Confidential Information.','This chunk defines exceptions to the confidentiality obligations outlined in Clause 2.'),
('NDA-PERMITTED-DISCLOSURE','v1','nda_permitted_disclosure','Permitted Disclosure','standard',array['NDA']::text[],0.0,null,'The Receiving Party may disclose Confidential Information (a) to its Representatives, provided it procures their compliance with this Agreement, and (b) to the extent required by Applicable Law or by any court or regulatory authority, provided that, where lawful, it gives the Disclosing Party prompt notice so that it may seek a protective order.','This chunk defines the conditions under which the Receiving Party may disclose Confidential Information, including to its Representatives and as required by law, within the Mutual Non-Disclosure Agreement.'),
('NDA-MAS-DISCLOSURE','v1','nda_permitted_disclosure','Disclosure to Regulators','fallback',array['NDA']::text[],0.2,'NDA-PERMITTED-DISCLOSURE','Nothing in this Agreement prevents either party from disclosing Confidential Information to the Monetary Authority of Singapore or any other regulatory authority having jurisdiction over it in the course of routine supervision or inspection, and no notice to the Disclosing Party is required for such disclosure.','This chunk is part of the disclosure provisions, specifically addressing how the agreement allows for the disclosure of confidential information to regulatory authorities without the need for prior notice.'),
('NDA-RETURN-DESTROY','v1','nda_return','Return or Destruction','standard',array['NDA']::text[],0.0,null,'On written request of the Disclosing Party, the Receiving Party shall promptly return or destroy all documents containing Confidential Information, except that it may retain copies required by Applicable Law or held in automatic electronic back-up systems, which remain subject to Clause 2 (Confidentiality Obligations).','This chunk outlines the obligations of the Receiving Party regarding the return or destruction of Confidential Information, following a written request from the Disclosing Party.'),
('NDA-NO-LICENCE','v1','nda_no_licence','No Licence or Warranty','standard',array['NDA']::text[],0.0,null,'All Confidential Information remains the property of the Disclosing Party. No licence of any intellectual property is granted, and Confidential Information is provided as is without any warranty as to its accuracy or completeness.','This chunk is located in Clause 7 of the Mutual Non-Disclosure Agreement, addressing the ownership and warranties related to the Confidential Information.'),
('NDA-TERM-2Y','v1','nda_term','Duration','standard',array['NDA']::text[],0.0,null,'This Agreement continues for two years from the date of this Agreement. The obligations in Clause 2 (Confidentiality Obligations) survive for a further two years after expiry or termination.','This chunk specifies the duration of the agreement and the survival period of confidentiality obligations after the agreement expires or terminates.'),
('NDA-TERM-3Y','v1','nda_term','Duration (Three Years)','fallback',array['NDA']::text[],0.2,'NDA-TERM-2Y','This Agreement continues for three years from the date of this Agreement. The obligations in Clause 2 (Confidentiality Obligations) survive for a further three years after expiry or termination.','This chunk refers to the duration of the Mutual Non-Disclosure Agreement and the survival period of confidentiality obligations.'),
('NDA-TERM-5Y','v1','nda_term','Duration (Extended)','fallback',array['NDA']::text[],0.4,'NDA-TERM-2Y','This Agreement continues for five years from the date of this Agreement, and the obligations in Clause 2 (Confidentiality Obligations) in respect of portfolio holdings and trading strategies continue indefinitely for so long as that information remains confidential.','This chunk refers to the duration of the agreement and the indefinite continuation of confidentiality obligations for specific types of information.'),
('NDA-REMEDIES','v1','nda_remedies','Remedies','standard',array['NDA']::text[],0.0,null,'Each party acknowledges that damages alone may not be an adequate remedy for breach of this Agreement and that the Disclosing Party is entitled to seek injunctive relief or specific performance, without prejudice to any other remedy.','This chunk is located under Clause 9 (Remedies) in the Mutual Non-Disclosure Agreement (NDA) template, outlining the consequences of a breach of the agreement.'),
('NDA-NON-SOLICIT-12M','v1','nda_non_solicitation','Non-Solicitation','optional',array['NDA']::text[],0.0,null,'For twelve months from the date of this Agreement, neither party shall, directly or indirectly, solicit or entice away any employee of the other party with whom it had contact in connection with the Purpose, save that general recruitment advertisements not targeted at such employees are permitted.','This chunk is part of the Non-Solicitation clause (S6) within the Mutual Non-Disclosure Agreement, outlining restrictions on soliciting employees of the other party for a period of twelve months.'),
('NDA-NON-SOLICIT-6M','v1','nda_non_solicitation','Non-Solicitation (Six Months)','fallback',array['NDA']::text[],0.3,'NDA-NON-SOLICIT-12M','For six months from the date of this Agreement, neither party shall solicit any employee of the other party who was directly involved in the Purpose, save through general advertisements or recruitment agencies acting without specific instruction.','This chunk is part of the Non-Solicitation clause (S7) and specifies the duration and conditions for soliciting employees of the other party.'),
('NDA-STANDSTILL','v1','nda_standstill','Standstill','optional',array['NDA']::text[],0.0,null,'For twelve months from the date of this Agreement, the counterparty shall not, without the prior written consent of the Investment Manager, acquire or offer to acquire any interest in the Investment Manager or any fund managed by it, other than through ordinary subscriptions for Shares on the terms of the Fund Documents.','This chunk is part of Clause S8, detailing restrictions on the counterparty''s actions regarding the Investment Manager and its funds for a period of twelve months.'),
('NDA-RESIDUALS','v1','nda_residuals','Residual Knowledge','optional',array['NDA']::text[],0.0,null,'Nothing in this Agreement restricts the Receiving Party from using general skills, know-how and experience retained in the unaided memory of its Representatives, provided that this does not permit disclosure of the source of such information or of any portfolio holdings, pricing or client identities.','This chunk is located in S9 of the document, discussing the permissible use of general skills and experience by the Receiving Party without disclosing specific confidential information.'),
('IMA-APPOINTMENT','v1','ima_appointment','Appointment','standard',array['IMA']::text[],0.0,null,'The Client appoints the Investment Manager to manage the Portfolio on a discretionary basis in accordance with the investment objective and restrictions in Clause 3 (Investment Objective and Restrictions), and the Investment Manager accepts the appointment.','This chunk is located in Section 2, where the Client formally appoints the Investment Manager to manage the Portfolio.'),
('IMA-INVESTMENT-RESTRICTIONS','v1','ima_investment_restrictions','Investment Objective and Restrictions','standard',array['IMA']::text[],0.0,null,'The Investment Manager shall manage the Portfolio in accordance with the investment objective, strategy and restrictions set out in the Schedule and Applicable Law. Any breach of a restriction caused by market movements shall be remedied within ten Business Days, taking due account of the interests of the Client.','This chunk defines the Investment Manager''s responsibilities under Clause 3, detailing how the Portfolio will be managed and how breaches of restrictions will be addressed.'),
('IMA-ESG-EXCLUSIONS','v1','ima_esg','Sustainability Exclusions','optional',array['IMA']::text[],0.0,null,'The Investment Manager shall not invest the Portfolio in issuers that derive more than ten per cent. of revenue from thermal coal mining, controversial weapons or tobacco production, as determined by reference to a recognised data provider, and shall report on compliance with this clause in each report under Clause 8 (Reports).','This chunk outlines the sustainability exclusions clause, which restricts investments in certain sectors and requires reporting on compliance.'),
('IMA-LEVERAGE-LIMIT','v1','ima_leverage','Borrowing and Leverage','optional',array['IMA']::text[],0.0,null,'The Investment Manager shall not borrow on behalf of the Client or use derivatives to create gross exposure exceeding one hundred and fifty per cent. of the Net Asset Value of the Portfolio, and shall notify the Client within one Business Day of any breach of this limit.','This chunk is part of the "Borrowing and Leverage" clause (S2) in the Investment Management Agreement, detailing the restrictions on borrowing and derivative usage by the Investment Manager.'),
('IMA-REGULATORY-STATUS','v1','ima_regulatory_status','Regulatory Status','standard',array['IMA']::text[],0.0,null,'The Investment Manager represents that it holds a capital markets services licence for fund management under the Securities and Futures Act 2001 and undertakes to notify the Client promptly of any suspension, revocation or material condition imposed on that licence by the Monetary Authority of Singapore.','This chunk is situated in Clause 4 of the Investment Management Agreement, detailing the Investment Manager''s regulatory status and obligations.'),
('IMA-CUSTODY','v1','ima_custody','Custody','standard',array['IMA']::text[],0.0,null,'The assets of the Portfolio shall be held by the Custodian. The Investment Manager shall not hold client money or assets and is not responsible for the acts or omissions of the Custodian, but shall give the Custodian proper instructions for the settlement of transactions.','This chunk defines the role of the Custodian and the responsibilities of the Investment Manager regarding the Portfolio''s assets, situated under Clause 5 of the Investment Management Agreement.'),
('IMA-BEST-EXECUTION','v1','ima_best_execution','Best Execution','standard',array['IMA']::text[],0.0,null,'The Investment Manager shall take all sufficient steps to obtain the best possible result for the Client when executing orders, having regard to price, costs, speed, likelihood of execution and settlement, and shall provide its order execution policy on request.','This chunk is part of Clause 6, which outlines the Investment Manager''s obligation to execute orders in the best possible manner for the Client.'),
('IMA-CONFLICTS','v1','ima_conflicts','Conflicts of Interest','standard',array['IMA']::text[],0.0,null,'The Investment Manager shall maintain arrangements to identify and manage conflicts of interest, shall allocate investment opportunities and aggregated orders fairly between the Client and its other clients, and shall disclose to the Client any material conflict it cannot manage.','This chunk is part of the "Conflicts of Interest" clause, which outlines the Investment Manager''s responsibilities in managing potential conflicts and ensuring fair treatment of the Client.'),
('IMA-SOFT-DOLLAR','v1','ima_soft_dollar','Soft Dollar Arrangements','optional',array['IMA']::text[],0.0,null,'The Investment Manager may receive research or advisory services from brokers in return for directing transactions to them only where the services assist in the management of the Portfolio, best execution is maintained and the arrangements are disclosed to the Client in the periodic reports.','This chunk describes the policy on soft dollar arrangements, detailing how the Investment Manager may receive research or advisory services from brokers under certain conditions.'),
('IMA-PROXY-VOTING','v1','ima_proxy_voting','Voting Rights','optional',array['IMA']::text[],0.0,null,'The Investment Manager shall exercise, or instruct the Custodian to exercise, voting rights attached to investments in the Portfolio in accordance with its proxy voting policy, and shall provide the Client with an annual summary of votes cast.','This chunk pertains to Clause S4 of the Investment Management Agreement, detailing the Investment Manager''s responsibility regarding the exercise of voting rights and reporting to the Client.'),
('IMA-REPORTING-MONTHLY','v1','ima_reporting','Reports','standard',array['IMA']::text[],0.0,null,'The Investment Manager shall send the Client a statement of the Portfolio within ten Business Days after the end of each month, showing holdings, transactions and the Net Asset Value, and a performance report within twenty Business Days after the end of each quarter.','This chunk describes the reporting obligations of the Investment Manager to the Client, including monthly statements and quarterly performance reports.'),
('IMA-REPORTING-QUARTERLY','v1','ima_reporting','Reports (Quarterly)','fallback',array['IMA']::text[],0.2,'IMA-REPORTING-MONTHLY','The Investment Manager shall send the Client a statement of the Portfolio, including holdings, transactions, Net Asset Value and performance, within twenty Business Days after the end of each calendar quarter.','This chunk describes the frequency and content of the quarterly reports the Investment Manager is required to provide to the Client, as outlined in Clause 8 of the Investment Management Agreement.'),
('IMA-MGMT-FEE','v1','ima_management_fee','Management Fee','standard',array['IMA']::text[],0.0,null,'The Client shall pay the Investment Manager a Management Fee at the rate of 1.5 per cent. per annum of the Net Asset Value of the Portfolio, calculated on each valuation day and payable monthly in arrears within ten Business Days of invoice.','This chunk defines the Management Fee payable by the Client to the Investment Manager, specifying the rate, calculation method, and payment terms.'),
('IMA-MGMT-FEE-TIERED','v1','ima_management_fee','Management Fee (Tiered)','fallback',array['IMA']::text[],0.4,'IMA-MGMT-FEE','The Client shall pay the Investment Manager a Management Fee of 1.5 per cent. per annum on the first fifty million Singapore dollars of Net Asset Value, 1.25 per cent. per annum on the next fifty million and 1.0 per cent. per annum on any excess, payable monthly in arrears.','This chunk describes the tiered Management Fee structure, specifying the rates and thresholds for different levels of Net Asset Value.'),
('IMA-PERF-FEE','v1','ima_performance_fee','Performance Fee','standard',array['IMA']::text[],0.0,null,'The Client shall pay the Investment Manager a Performance Fee equal to twenty per cent. of the increase in Net Asset Value of the Portfolio above the High-Water Mark over each calendar year, payable within twenty Business Days after the year end.','This chunk defines the Performance Fee and when it is payable, which is part of the Investment Management Agreement''s fee structure.'),
('IMA-PERF-FEE-HURDLE','v1','ima_performance_fee','Performance Fee (Hurdle)','fallback',array['IMA']::text[],0.4,'IMA-PERF-FEE','A Performance Fee of twenty per cent. is payable only on the return of the Portfolio in excess of a hurdle of eight per cent. per annum, and only to the extent that the Net Asset Value also exceeds the High-Water Mark, calculated annually.','This chunk describes the Performance Fee (Hurdle) clause, which outlines the conditions under which a Performance Fee is payable.'),
('IMA-LIAB-GROSS-NEG','v1','ima_liability','Liability of the Investment Manager','standard',array['IMA']::text[],0.0,null,'The Investment Manager shall not be liable for any Losses suffered by the Client except to the extent caused by the negligence, wilful default or fraud of the Investment Manager or its breach of Applicable Law. The Investment Manager is not liable for Losses resulting from investment decisions made in good faith in accordance with Clause 3 (Investment Objective and Restrictions).','This chunk defines the liability of the Investment Manager, specifying the conditions under which the Investment Manager is not liable for losses suffered by the Client.'),
('IMA-LIAB-CAP-FEES','v1','ima_liability','Liability Cap','fallback',array['IMA']::text[],0.5,'IMA-LIAB-GROSS-NEG','Subject to Clause 11 (Liability of the Investment Manager), the aggregate liability of the Investment Manager in any calendar year shall not exceed the Management Fee received in respect of that year, except in the case of fraud or wilful default.','This chunk describes the Liability Cap clause, which limits the Investment Manager''s liability to the Management Fee received in a calendar year, except for fraud or wilful default, and is situated after the Management Fee (Tiered) clause.'),
('IMA-INDEMNITY-CLIENT','v1','ima_indemnity','Indemnity','standard',array['IMA']::text[],0.0,null,'The Client shall indemnify the Investment Manager against all Losses incurred in the proper performance of its duties under this Agreement, except Losses caused by the negligence, wilful default or fraud of the Investment Manager.','This chunk is part of Clause 12, which outlines the indemnity obligations of the Client towards the Investment Manager.'),
('IMA-INDEMNITY-MUTUAL','v1','ima_indemnity','Mutual Indemnity','fallback',array['IMA']::text[],0.5,'IMA-INDEMNITY-CLIENT','Each party shall indemnify the other against all Losses arising from its own breach of this Agreement, negligence, wilful default or fraud, provided that the indemnified party notifies the claim promptly and does not settle it without consent.','This chunk is part of the "Mutual Indemnity" clause (S9) in the Investment Management Agreement, detailing the indemnification obligations between the parties.'),
('IMA-KEY-PERSON','v1','ima_key_person','Key Person','optional',array['IMA']::text[],0.0,null,'If any Key Person ceases to be involved in the management of the Portfolio, the Investment Manager shall notify the Client within five Business Days and the Client may, within thirty days of that notice, terminate this Agreement with immediate effect without paying any termination fee.','This chunk defines the responsibilities and consequences if a Key Person stops managing the Portfolio, allowing the Client to terminate the agreement under specific conditions.'),
('DIST-APPOINTMENT-NONEXCL','v1','dist_appointment','Appointment of Distributor','standard',array['DIST']::text[],0.0,null,'The Investment Manager appoints the Distributor on a non-exclusive basis to market the Shares to Eligible Investors in the Territory, and the Distributor accepts the appointment on the terms of this Agreement.','This chunk is located in Section 2 of the Distribution Agreement, detailing the appointment of the Distributor by the Investment Manager.'),
('DIST-APPOINTMENT-EXCL','v1','dist_appointment','Exclusive Appointment','fallback',array['DIST']::text[],0.6,'DIST-APPOINTMENT-NONEXCL','The Investment Manager appoints the Distributor as its exclusive distributor of the Shares to Eligible Investors in the Territory for an initial period of two years, during which the Investment Manager shall not appoint any other distributor in the Territory, save for its own direct marketing.','This chunk describes the exclusive appointment clause, specifying the distributor''s role and the exclusivity period.'),
('DIST-SELLING-RESTRICTIONS','v1','dist_selling_restrictions','Selling Restrictions','standard',array['DIST']::text[],0.0,null,'The Distributor shall offer the Shares only to Eligible Investors, shall not make any offer to the retail public or any offer requiring a prospectus, and shall comply with the selling restrictions in the Fund Documents for each jurisdiction in the Territory.','This chunk is part of Clause 3 (Selling Restrictions) in the Distribution Agreement, detailing the obligations of the Distributor regarding the marketing and sale of Shares to Eligible Investors.'),
('DIST-MARKETING-MATERIALS','v1','dist_marketing','Marketing Materials','standard',array['DIST']::text[],0.0,null,'The Distributor shall use only marketing materials approved in writing by the Investment Manager and shall not make any representation about the Fund that is inconsistent with the Fund Documents.','This chunk is part of Clause 5 (Marketing Materials) in the Distribution Agreement, outlining the Distributor''s obligation to use approved marketing materials and adhere to the Fund Documents.'),
('DIST-REGULATORY-COMPLIANCE','v1','dist_regulatory','Regulatory Compliance','standard',array['DIST']::text[],0.0,null,'The Distributor represents that it holds, or is exempt from holding, all licences required under the Securities and Futures Act 2001 and the Financial Advisers Act 2001 to perform its obligations, and shall comply with all Applicable Law in the Territory.','This chunk is situated in Section 5 of the document, which deals with Regulatory Compliance.'),
('DIST-INVESTOR-CDD','v1','dist_cdd','Investor Due Diligence','standard',array['DIST']::text[],0.0,null,'The Distributor shall perform customer due diligence on each investor it introduces in accordance with Clause 13 (Anti-Money Laundering and Customer Due Diligence) and shall provide copies of the due diligence records to the Investment Manager or the Fund''s administrator within two Business Days of request.','This chunk is part of the Investor Due Diligence section, detailing the Distributor''s obligation to perform due diligence on investors and provide records to the Investment Manager.'),
('DIST-REMUNERATION-TRAILER','v1','dist_remuneration','Remuneration','standard',array['DIST']::text[],0.0,null,'In consideration of its services the Distributor shall receive a trailer fee equal to thirty per cent. of the Management Fee received by the Investment Manager in respect of Shares held by investors introduced by the Distributor, payable quarterly in arrears.','This chunk is located in Clause 7 of the Distribution Agreement, detailing the remuneration for the Distributor''s services.'),
('DIST-REMUNERATION-FLAT','v1','dist_remuneration','Remuneration (Fixed Fee)','fallback',array['DIST']::text[],0.4,'DIST-REMUNERATION-TRAILER','The Distributor shall receive a fixed placement fee of one per cent. of the Subscription Amount of each investor it introduces, payable within thirty days of the relevant Dealing Day, and no other remuneration.','This chunk describes the remuneration structure for the Distributor under Clause S2, detailing the fixed fee and payment terms.'),
('DIST-SUB-DISTRIBUTORS','v1','dist_sub_distribution','Sub-Distributors','optional',array['DIST']::text[],0.0,null,'The Distributor may appoint sub-distributors in the Territory only with the prior written consent of the Investment Manager, shall ensure each sub-distributor is bound by obligations equivalent to Clause 3 (Selling Restrictions), and remains liable for their acts and omissions.','This chunk is part of the Sub-Distributors clause (S3) within the Distribution Agreement, detailing the conditions under which the Distributor can appoint sub-distributors.'),
('DIST-COMPLAINTS','v1','dist_complaints','Complaints','standard',array['DIST']::text[],0.0,null,'The Distributor shall notify the Investment Manager within two Business Days of any complaint from an investor relating to the Fund and shall co-operate in its investigation and resolution.','This chunk is part of Clause 8, which outlines the Distributor''s obligations in handling investor complaints related to the Fund.'),
('DIST-AUDIT-RIGHTS','v1','dist_audit','Audit and Records','standard',array['DIST']::text[],0.0,null,'The Distributor shall keep complete records of its activities under this Agreement for at least five years and shall permit the Investment Manager or its auditors, on ten Business Days'' notice, to inspect those records to verify compliance with Clause 3 (Selling Restrictions).','This chunk is part of Clause 9 (Audit and Records) which outlines the Distributor''s obligations regarding record-keeping and record inspection for compliance with selling restrictions.'),
('DIST-INDEMNITY','v1','dist_indemnity','Indemnity','standard',array['DIST']::text[],0.0,null,'The Distributor shall indemnify the Investment Manager and the Fund against all Losses arising from any breach by the Distributor of Clause 3 (Selling Restrictions) or Clause 4 (Marketing Materials), or any misrepresentation made by it to an investor.','This chunk is part of the Indemnity clause (Clause 10) in the Distribution Agreement, outlining the Distributor''s obligation to protect the Investment Manager and the Fund from certain losses.'),
('SIDE-MFN','v1','side_mfn','Most Favoured Nation','optional',array['SIDE']::text[],0.0,null,'If the Investment Manager enters into a side letter with any Similar Investor granting rights more favourable than those granted to the Investor, the Investment Manager shall notify the Investor within thirty days and the Investor may elect, within thirty days of that notice, to receive the same rights on the same terms and conditions.','This chunk is part of the "Most Favoured Nation" clause (S1) in the document, detailing the conditions under which an investor can receive rights equivalent to those granted to other similar investors.'),
('SIDE-MFN-LIMITED','v1','side_mfn','Most Favoured Nation (Limited)','fallback',array['SIDE']::text[],0.4,'SIDE-MFN','The Investor may elect to receive any more favourable rights granted to a Similar Investor, except rights relating to fees, capacity or co-investment, rights granted to address the legal or regulatory requirements of a particular investor, and rights granted to investors whose subscription exceeds that of the Investor.','This chunk is part of the "Most Favoured Nation (Limited)" clause, which outlines the conditions under which an investor can receive more favourable rights than initially agreed upon.'),
('SIDE-FEE-REBATE','v1','side_fee_rebate','Management Fee Rebate','optional',array['SIDE']::text[],0.0,null,'The Investment Manager shall rebate to the Investor an amount equal to 0.25 per cent. per annum of the Net Asset Value of the Investor''s Shares out of the Management Fee it receives, calculated monthly and paid quarterly in arrears, either in cash or by issue of additional Shares.','This chunk describes the Management Fee Rebate clause, which is part of the Fallback and Optional Clauses section, detailing specific benefits and rights for the Investor.'),
('SIDE-EXCUSE-ESG','v1','side_excuse','Excuse Rights','optional',array['SIDE']::text[],0.0,null,'The Investor may be excused from participating in any investment by the Fund in issuers engaged in the production of controversial weapons or thermal coal, and the Investment Manager shall make such arrangements, including through a separate share class, as are reasonably necessary to give effect to this right.','This chunk describes the Excuse Rights clause, allowing the Investor to opt-out of investments in controversial weapons or thermal coal issuers, and outlines the Investment Manager''s obligations to facilitate this.'),
('SIDE-TRANSPARENCY','v1','side_transparency','Additional Reporting','optional',array['SIDE']::text[],0.0,null,'The Investment Manager shall provide the Investor, within thirty days after each quarter end, with a look-through report of the Fund''s holdings, exposures by sector and country, and the top ten positions, which the Investor shall treat as confidential in accordance with Clause 3 (Confidentiality).','This chunk describes the Additional Reporting clause, which outlines the Investor''s right to receive quarterly reports from the Investment Manager.'),
('SIDE-KEY-PERSON-NOTICE','v1','side_key_person','Key Person Notification','optional',array['SIDE']::text[],0.0,null,'The Investment Manager shall notify the Investor within five Business Days if any Key Person ceases to devote substantially all of his or her business time to the Fund, and the Investor may redeem its Shares on the next Dealing Day without any redemption fee or notice period.','This chunk is part of the Key Person Notification clause (S6) in the document, detailing the procedures for notifying the Investor and the Investor''s redemption rights.'),
('SIDE-TRANSFER-AFFILIATE','v1','side_transfer','Transfers to Affiliates','optional',array['SIDE']::text[],0.0,null,'Notwithstanding the Fund Documents, the Investor may transfer all or part of its Shares to an Affiliate without the consent of the directors of the Fund, subject only to the transferee satisfying the customer due diligence requirements of the Fund.','This chunk describes the conditions under which an Investor may transfer its Shares to an Affiliate, situated as S7 in the document.'),
('SIDE-COINVEST','v1','side_coinvestment','Co-Investment Opportunities','optional',array['SIDE']::text[],0.0,null,'The Investment Manager shall use reasonable efforts to notify the Investor of any co-investment opportunity offered to other investors alongside the Fund, and the Investor may participate on terms no less favourable than those offered to other co-investors, subject to allocation at the discretion of the Investment Manager.','This chunk is part of Clause S8, detailing co-investment opportunities for the investor.'),
('SIDE-CAPACITY','v1','side_capacity','Capacity Rights','optional',array['SIDE']::text[],0.0,null,'If the Fund is closed to new subscriptions, the Investor shall remain entitled to make additional subscriptions of up to fifty million Singapore dollars in aggregate over the following two years.','This chunk describes the rights of an investor to make additional subscriptions if the fund is closed to new subscriptions, falling under the Capacity Rights clause.'),
('SIDE-REGULATORY-INFO','v1','side_regulatory_information','Regulatory Information','optional',array['SIDE']::text[],0.0,null,'The Investment Manager shall provide the Investor promptly on request with such information about the Fund as the Investor reasonably requires to meet its own regulatory, tax or reporting obligations, including information requested by its regulator.','This chunk is located at the end of the document, providing information on the Investor''s right to request regulatory, tax, or reporting information from the Investment Manager.'),
('SIDE-PRECEDENCE','v1','side_precedence','Precedence','standard',array['SIDE']::text[],0.0,null,'This letter supplements the Fund Documents. In the event of any conflict between this letter and the Fund Documents, this letter shall prevail as between the Investor and the Fund.','This chunk is located under the "Precedence" section, which defines the relationship and precedence between this letter and the Fund Documents in case of any conflicts.'),
('SUBS-SUBSCRIPTION','v1','subs_subscription','Subscription','standard',array['SUBS']::text[],0.0,null,'The Investor irrevocably applies to subscribe for Shares for the Subscription Amount at the Net Asset Value per Share on the relevant Dealing Day, on the terms of the Fund Documents.','This chunk describes the subscription process for the Investor, detailing the application to purchase Shares at the Net Asset Value per Share on the relevant Dealing Day.'),
('SUBS-PAYMENT','v1','subs_payment','Payment','standard',array['SUBS']::text[],0.0,null,'The Subscription Amount shall be paid in cleared funds to the account of the Fund at least three Business Days before the relevant Dealing Day. If payment is not received in time, the subscription may be deferred to the next Dealing Day.','This chunk describes the payment terms for the subscription amount, specifying when and how the payment should be made.'),
('SUBS-INVESTOR-REPS-AI','v1','subs_eligibility','Investor Representations','standard',array['SUBS']::text[],0.0,null,'The Investor represents that it is an Eligible Investor and, in particular, an accredited investor within the meaning of section 4A of the Securities and Futures Act 2001, that it has not opted out of accredited investor status, and that it is subscribing for its own account.','This chunk is located in Clause 4 of the Subscription Agreement, detailing the representations made by the Investor.'),
('SUBS-INVESTOR-REPS-INSTITUTIONAL','v1','subs_eligibility','Investor Representations (Institutional)','fallback',array['SUBS']::text[],0.3,'SUBS-INVESTOR-REPS-AI','The Investor represents that it is an institutional investor within the meaning of section 4A of the Securities and Futures Act 2001, such as a bank, insurer, pension fund or government entity, and that it is subscribing as principal.','This chunk is part of the Investor Representations (Institutional) section, which is the first section (S1) of the Subscription Agreement.'),
('SUBS-SOURCE-OF-FUNDS','v1','subs_source_of_funds','Source of Funds','standard',array['SUBS']::text[],0.0,null,'The Investor represents that the Subscription Amount is not derived from any unlawful activity and undertakes to provide such information on its source of funds and source of wealth as the Fund may require under Clause 11 (Anti-Money Laundering and Customer Due Diligence).','This chunk is located in Section 5 of the Subscription Agreement, addressing the Investor''s representation regarding the lawful origin of the Subscription Amount and the provision of required information on sources of funds and wealth.'),
('SUBS-TRANSFER-RESTRICTIONS','v1','subs_transfer','Transfer Restrictions','standard',array['SUBS']::text[],0.0,null,'The Investor shall not transfer any Shares without the prior written consent of the directors of the Fund, which may be withheld if the transferee is not an Eligible Investor or would cause the Fund to breach Applicable Law.','This chunk pertains to the restrictions on transferring Shares, outlining the conditions under which transfers can be made and the consent required from the Fund''s directors.'),
('SUBS-REDEMPTION-MONTHLY','v1','subs_redemption','Redemption','standard',array['SUBS']::text[],0.0,null,'The Investor may redeem Shares on any Dealing Day by giving at least thirty days'' written notice to the administrator. Redemption proceeds are normally paid within ten Business Days after the Dealing Day.','This chunk describes the redemption process for Shares, which is part of the Subscription Agreement.'),
('SUBS-REDEMPTION-QUARTERLY','v1','subs_redemption','Redemption (Quarterly)','fallback',array['SUBS']::text[],0.4,'SUBS-REDEMPTION-MONTHLY','The Investor may redeem Shares only as at the last Dealing Day of each calendar quarter by giving at least sixty days'' written notice, and redemption proceeds are paid within twenty Business Days.','This chunk describes the quarterly redemption process for Investors, detailing the notice period and payment timeframe.'),
('SUBS-GATE','v1','subs_gate','Redemption Gate','optional',array['SUBS']::text[],0.0,null,'The directors of the Fund may limit total redemptions on any Dealing Day to ten per cent. of the Net Asset Value of the Fund, in which case redemption requests shall be reduced pro rata and the balance carried forward to the next Dealing Day with priority.','This chunk describes the Redemption Gate clause, which is part of the Fallback and Optional Clauses section, specifically detailing how the Fund''s directors can limit redemptions.'),
('SUBS-IN-SPECIE','v1','subs_in_specie','Redemption in Specie','optional',array['SUBS']::text[],0.0,null,'With the consent of the Investor, the directors of the Fund may satisfy a redemption request in whole or in part by transferring assets of the Fund in specie, valued on the same basis as used to calculate the Net Asset Value.','This chunk describes the conditions under which redemption requests can be satisfied with assets of the Fund in their entirety or in part, as agreed by the Investor.'),
('SUBS-TAX-FATCA-CRS','v1','subs_tax','Tax Information','standard',array['SUBS']::text[],0.0,null,'The Investor shall provide such self-certification forms and information as the Fund requires to comply with the United States Foreign Account Tax Compliance Act and the Common Reporting Standard as implemented in Singapore, and shall update them within thirty days of any change in circumstances.','This chunk is situated under Clause 8 of the Subscription Agreement, which deals with tax information requirements for the Investor.'),
('SUBS-RISK-ACK','v1','subs_risk','Risk Acknowledgement','standard',array['SUBS']::text[],0.0,null,'The Investor acknowledges that it has read the Fund Documents, that an investment in the Fund involves a high degree of risk including the possible loss of the entire Subscription Amount, and that it has obtained such independent advice as it considers appropriate.','This chunk is situated under Clause 9, which deals with the Investor''s acknowledgment of the risks involved in the investment and the independent advice obtained.'),
('SUBS-INDEMNITY-INVESTOR','v1','subs_indemnity','Indemnity','standard',array['SUBS']::text[],0.0,null,'The Investor shall indemnify the Fund, the Investment Manager and the administrator against all Losses arising from any representation in Clause 4 (Investor Representations) being untrue or misleading.','This chunk is located in Clause 10 of the Subscription Agreement, detailing the Investor''s obligation to indemnify the Fund, the Investment Manager, and the administrator for any losses arising from false or misleading representations made by the Investor.')
